/**
 * Разбор аргументов, которые модель передала в инструмент расчёта.
 *
 * ЭТО ГРАНИЦА ДОВЕРИЯ. Всё, что приходит сюда, придумала языковая модель по
 * тексту живого человека. Она передаст «трёхметровый», «примерно 3м», «ну
 * обычный», null, пустую строку и слово «балкон» в поле типа остекления.
 * Бриф прямо предупреждает: «Model passes address as null — validate in the
 * sub-flow, don't trust it».
 *
 * Поэтому здесь не «приведение типов», а разбор естественного языка с явным
 * отказом. Чего не поняли — о том честно сообщаем наверх, и агент переспросит.
 * Молча подставить значение по умолчанию нельзя: клиент увидит цену за лоджию
 * 6 метров там, где у него балкон 3 метра, и это будет наша вина.
 */
'use strict';

/** Нормализация под сравнение: регистр, ё, дефисы, лишние пробелы. */
function fold(value) {
  if (value == null) return '';
  return String(value)
    .toLowerCase()
    .replace(/ё/g, 'е')
    .replace(/[-–—_]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

/**
 * Конфигурация балкона.
 *
 * Порядок проверок важен. «П-образная лоджия» содержит и «лоджия», и «п
 * образн» — выиграть должно «п образн», потому что форма определяет метраж
 * сильнее, чем название помещения.
 */
function parseConfiguration(raw) {
  const t = fold(raw);
  if (!t) return null;

  if (/(^|\s)(п образн|побразн|п образный|углов)/.test(t)) return 'pshaped';
  if (/лодж/.test(t)) return 'loggia6';
  if (/(^|\s)(прям|балкон)/.test(t)) return 'straight3';

  // Иногда модель передаёт только длину.
  const metres = t.match(/(\d+(?:[.,]\d+)?)\s*(?:м|метр)/);
  if (metres) {
    const n = parseFloat(metres[1].replace(',', '.'));
    if (Number.isFinite(n)) return n >= 5 ? 'loggia6' : 'straight3';
  }

  // Английские ключи — на случай, если модель передала их из описания инструмента.
  if (/^(straight3|pshaped|loggia6)$/.test(t)) return t;

  return null;
}

/** Тип остекления. Отдельная функция: ошибка здесь меняет цену на четверть. */
function parseGlazing(raw) {
  const t = fold(raw);
  if (!t) return null;
  if (/(тепл|утепл|зим|жил)/.test(t)) return 'warm';
  if (/(холод|не тепл|летн)/.test(t)) return 'cold';
  if (/^(warm|cold)$/.test(t)) return t;
  return null;
}

/** Класс профиля — необязателен: без него отдаём вилку от эконома до премиума. */
function parseTier(raw) {
  const t = fold(raw);
  if (!t) return null;
  if (/(эконом|дешев|подешевл|бюджет|минимальн)/.test(t)) return 'economy';
  if (/(премиум|максимальн|лучш|дорог|топ)/.test(t)) return 'premium';
  if (/(стандарт|средн|обычн|оптимальн)/.test(t)) return 'standard';
  if (/^(economy|standard|premium)$/.test(t)) return t;
  return null;
}

/**
 * Булев флаг из чего угодно.
 *
 * Модель присылает true, "true", "да", "yes", 1, "нужен", "не нужен".
 * `Boolean("не нужен")` равен true — поэтому отрицания проверяются первыми,
 * иначе «крыша не нужна» превратится в наценку 18 %.
 */
function parseFlag(raw) {
  if (raw === true) return true;
  if (raw === false) return false;
  const t = fold(raw);
  if (!t) return false;
  if (/(^|\s)(не|нет|без)(\s|$)/.test(t)) return false;
  // Основа «нуж», а не «нужн»: в мужском роде беглая гласная даёт «нужен»,
  // и стем «нужн» его не ловит. На этом тест и поймал ошибку — «нужен вынос»
  // читался как «вынос не нужен» и тихо срезал 22 % из сметы.
  return /(^|\s)(да|нуж|надо|есть|true|yes|1|последн|верхн)/.test(t);
}

/** Этаж — только чтобы понять, последний ли он. Само число на цену не влияет. */
function parseFloor(raw) {
  if (raw == null || raw === '') return null;
  const n = parseInt(String(raw).replace(/\D+/g, ''), 10);
  return Number.isFinite(n) && n > 0 && n < 200 ? n : null;
}

/**
 * Адрес нужен не для цены, а для проверки реальности объекта и для лида.
 * Районных цен у нас нет, и выдумывать наценку по району мы не будем —
 * поэтому адрес сюда попадает как есть, а решает по нему геокодер.
 */
function parseAddress(raw) {
  const s = raw == null ? '' : String(raw).trim().replace(/\s+/g, ' ');
  return s.slice(0, 300);
}

/**
 * @returns {{ok: boolean, value: object, missing: string[], notes: string[]}}
 *   ok — хватает ли данных для расчёта
 *   missing — что переспросить у человека, человеческими словами
 */
function parseEstimateArgs(args) {
  const a = args && typeof args === 'object' ? args : {};

  const configuration = parseConfiguration(
    a.configuration !== undefined ? a.configuration : a.balcony_type
  );
  const glazing = parseGlazing(a.glazing !== undefined ? a.glazing : a.glazing_type);
  const profileTier = parseTier(a.profile_tier !== undefined ? a.profile_tier : a.tier);
  const floor = parseFloor(a.floor);

  // Последний этаж можно узнать двумя путями, и оба надо принять: модель то
  // передаёт отдельный флаг, то пишет «последний» прямо в поле этажа.
  const topFlagGiven = a.top_floor !== undefined || a.is_top_floor !== undefined;
  const topFloor = topFlagGiven
    ? parseFlag(a.top_floor !== undefined ? a.top_floor : a.is_top_floor)
    : parseFlag(a.floor);

  const extension = parseFlag(a.extension !== undefined ? a.extension : a.with_extension);
  const address = parseAddress(a.address);

  const missing = [];
  if (!configuration) missing.push('конфигурация балкона: прямой 3 метра, П-образный или лоджия');
  if (!glazing) missing.push('тип остекления: тёплое или холодное');

  const notes = [];
  if (!profileTier) notes.push('класс профиля не указан — вилка от эконома до премиума');

  // Условие включает !topFloor намеренно. «последний» в поле этажа не даёт
  // числа, но даёт флаг крыши — и без этой проверки расчёт добавлял крышу и
  // одновременно писал, что крыши в нём нет. Заметка, противоречащая смете,
  // хуже отсутствующей: по ней заказчик спорит с собственной же цифрой.
  if (!topFloor && floor === null && !topFlagGiven) {
    notes.push('этаж не указан — крыша в расчёт не включена');
  }

  return {
    ok: missing.length === 0,
    missing,
    notes,
    value: {
      configuration,
      glazing,
      profileTier,
      topFloor,
      extension,
      floor,
      address,
    },
  };
}

// ---------------------------------------------------------------------------
//   источник: builds/02-lead-widget/estimate-input.js
//
// Всё, что приходит сюда, придумала языковая модель по фразе живого человека.
// Это граница доверия, а не приведение типов.
// ---------------------------------------------------------------------------
return $input.all().map((item) => {
  const parsed = parseEstimateArgs(item.json);
  return {
    json: {
      ...parsed.value,
      session_id: String(item.json.session_id || ''),
      args_ok: parsed.ok,
      missing: parsed.missing,
      missing_text: parsed.missing.join('; '),
      notes: parsed.notes,
      has_address: Boolean(parsed.value.address),
    },
  };
});

/**
 * Разбор ответа DaData «стандартизация адресов» в решение: считать или переспросить.
 *
 * Правило простое и на нём держится доверие к сборке: НЕТ ВНЯТНОГО АДРЕСА —
 * НЕТ ЦЕНЫ. Тест 3 из брифа именно про это: на «ул. Пушкина» бот обязан
 * переспросить, а не назвать сумму. Цена, названная по адресу, которого не
 * существует, — это счёт, который заказчик потом не выставит, и разговор,
 * который он проведёт с нами, а не с клиентом.
 *
 * Адрес НЕ влияет на стоимость. Районных прайсов у нас нет, и наценку по
 * району мы не изобретаем (см. PRICING-SOURCES.md). Адрес нужен, чтобы
 * (1) убедиться, что объект реальный, (2) убедиться, что он в зоне выезда,
 * (3) передать его замерщику в разобранном виде.
 *
 * Почему разбираем коды, а не смотрим на координаты: DaData отдаёт готовый
 * вердикт полями qc и qc_complete. Выводить то же самое из координат — писать
 * эвристику поверх сервиса, который уже ответил.
 */
'use strict';

/** Регионы, куда компания выезжает. Меняется при внедрении у заказчика. */
const SERVICE_REGIONS = ['самарская'];

/**
 * qc — нужна ли ручная проверка распознанного адреса.
 * Значения из документации DaData, не выдуманы.
 */
const QC = {
  CONFIDENT: 0, // распознан уверенно
  NEEDS_CHECK: 1, // лишние части или данных мало
  GARBAGE: 2, // пустой или заведомо мусорный
  AMBIGUOUS: 3, // есть альтернативные варианты
};

/**
 * qc_complete — годится ли адрес для доставки. Нам он говорит, чего не хватает.
 * Порядок в этой таблице — это порядок, в котором мы просим уточнить: нет
 * смысла спрашивать номер дома, если не назван город.
 */
const INCOMPLETE_REASON = {
  1: 'не указан регион',
  2: 'не указан город',
  3: 'не указана улица',
  4: 'не указан номер дома',
  6: 'адрес неполный',
  7: 'это адрес не в России',
};

function str(v) {
  return v == null ? '' : String(v).trim();
}

function firstRecord(response) {
  // DaData отвечает массивом даже на один адрес. Узел HTTP Request в n8n
  // отдаёт его то массивом, то объектом с полем data — принимаем оба.
  if (Array.isArray(response)) return response[0] || null;
  if (response && typeof response === 'object') {
    if (Array.isArray(response.data)) return response.data[0] || null;
    if (response.result !== undefined || response.qc !== undefined) return response;
  }
  return null;
}

function inServiceArea(region) {
  const r = str(region).toLowerCase().replace(/ё/g, 'е');
  if (!r) return false;
  return SERVICE_REGIONS.some((s) => r.includes(s));
}

/**
 * @returns {{ok: boolean, reason: string, ask: string, address: object}}
 *   ok      — можно ли считать смету
 *   reason  — техническая причина отказа, для лога
 *   ask     — что сказать человеку; пусто, если всё в порядке
 *   address — разобранный адрес для лида
 */
function interpretAddress(response) {
  const rec = firstRecord(response);

  if (!rec) {
    // Сервис не ответил или ответил непонятно. Это НЕ повод отказать человеку:
    // адрес на цену не влияет, а терять лид из-за сбоя стороннего сервиса —
    // худший из возможных исходов. Считаем, но помечаем адрес непроверенным.
    return {
      ok: true,
      degraded: true,
      reason: 'DaData не ответила — адрес не проверен',
      ask: '',
      address: { raw: '', result: '', city: '', street: '', house: '', region: '' },
    };
  }

  const address = {
    raw: str(rec.source),
    result: str(rec.result),
    region: str(rec.region_with_type) || str(rec.region),
    city: str(rec.city_with_type) || str(rec.city) || str(rec.settlement_with_type),
    district: str(rec.city_district_with_type),
    street: str(rec.street_with_type),
    house: str(rec.house),
    lat: str(rec.geo_lat),
    lon: str(rec.geo_lon),
    fias_level: rec.fias_level == null ? '' : String(rec.fias_level),
  };

  const qc = Number(rec.qc);
  const complete = Number(rec.qc_complete);

  if (qc === QC.GARBAGE) {
    return {
      ok: false,
      degraded: false,
      reason: 'qc=2: адрес пустой или мусорный',
      ask: 'Не разобрал адрес. Напишите, пожалуйста, город, улицу и номер дома.',
      address,
    };
  }

  // Иностранный адрес ловим раньше зоны выезда: человеку полезнее услышать
  // «мы работаем только в Самарской области», чем «не указан регион».
  if (complete === 7) {
    return {
      ok: false,
      degraded: false,
      reason: 'qc_complete=7: иностранный адрес',
      ask: 'Мы работаем в Самаре и Самарской области. Подскажите адрес объекта в этом регионе.',
      address,
    };
  }

  if (INCOMPLETE_REASON[complete]) {
    const what = INCOMPLETE_REASON[complete];
    return {
      ok: false,
      degraded: false,
      reason: `qc_complete=${complete}: ${what}`,
      ask: `Уточните, пожалуйста, адрес — ${what}.`,
      address,
    };
  }

  if (qc === QC.AMBIGUOUS) {
    return {
      ok: false,
      degraded: false,
      reason: 'qc=3: несколько подходящих адресов',
      ask: 'Таких адресов в городе несколько. Уточните, пожалуйста, район или полное название улицы.',
      address,
    };
  }

  // Регион определился, но не наш. Честно сказать сейчас дешевле, чем
  // отправить замерщика за 400 км и разбираться потом.
  if (address.region && !inServiceArea(address.region)) {
    return {
      ok: false,
      degraded: false,
      reason: `вне зоны выезда: ${address.region}`,
      ask: `Мы работаем в Самаре и Самарской области, а ${address.region} — за пределами выезда. Подсказать кого-то в вашем городе не смогу, но посчитать для объекта в Самарской области — с радостью.`,
      address,
    };
  }

  // qc=1 — данных маловато, но дом и город есть. Считаем, помечаем адрес
  // приблизительным: замерщик всё равно позвонит перед выездом.
  if (qc === QC.NEEDS_CHECK) {
    return {
      ok: true,
      degraded: true,
      reason: 'qc=1: адрес распознан неточно',
      ask: '',
      address,
    };
  }

  return { ok: true, degraded: false, reason: '', ask: '', address };
}

// ---------------------------------------------------------------------------
//   источник: builds/02-lead-widget/address.js
//
// Узел HTTP заменяет элемент ответом DaData, поэтому разобранные аргументы
// забираем обратно из узла разбора, а не из $json.
// ---------------------------------------------------------------------------
const args = $('Parse Estimate Args').first().json;

return $input.all().map((item) => {
  const verdict = interpretAddress(item.json);
  return {
    json: {
      ...args,
      address_ok: verdict.ok,
      address_degraded: verdict.degraded,
      address_reason: verdict.reason,
      address_ask: verdict.ask,
      address_clean: verdict.address,
    },
  };
});

/**
 * Остекление балконов — оценка стоимости по реальным опубликованным прайсам.
 *
 * ИСТОЧНИК (см. PRICING-SOURCES.md — там же даты, ссылки и все цифры):
 *   ООО ГК «Самстрой» / balkon63.ru — публикует настоящую матрицу
 *   8 профилей × 3 конфигурации для тёплого остекления, плюс цены «под ключ»
 *   для холодного. Цифры стабильные, не акционные.
 *
 * ГК «ИнРос» / inros63.ru проверен и ОТКЛОНЁН как источник цен: три страницы
 * сайта называют три разные цены «от» (39 150 / 51 130 / 36 190 ₽), и все под
 * вечным «скидка 60%, только до 14 сентября». Это рекламный якорь, а не
 * прайс-лист. Строить смету на таких числах нельзя.
 *
 * Ни одна цифра здесь не выдумана. Это правило из CLAUDE.md: никогда не
 * изобретать цены клиента. Оценка, построенная на придуманной матрице, — это
 * ложь, которую заказчик обнаружит при первом же звонке конкуренту.
 *
 * ЧТО ЭТО ВОЗВРАЩАЕТ: ВИЛКУ, а не одну цифру. Настоящая смета составляется
 * замерщиком на объекте. Виджет обязан дать честный диапазон и сказать, от чего
 * он зависит, иначе он обещает то, чего не может выполнить.
 *
 * Переносится в n8n Code node как есть — без импортов и Node-specific API.
 */

'use strict';

/**
 * Тёплое остекление «под ключ», руб. Источник: balkon63.ru, прайс 2026.
 * Ключ — конфигурация балкона, значение — [минимум по профилю, максимум].
 *
 * Минимум = Exprof Externa (самый доступный в прайсе).
 * Максимум = KBE-88 (самый дорогой в прайсе).
 */
const WARM_BY_CONFIG = {
  straight3: { low: 18050, high: 36722, label: 'прямой балкон 3 м' },
  pshaped: { low: 26840, high: 56090, label: 'П-образный балкон' },
  loggia6: { low: 33884, high: 69909, label: 'лоджия 6 м' },
};

/**
 * Классы профиля внутри матрицы Самстроя. Границы взяты по фактическим ценам
 * для прямого балкона 3 м, а не назначены произвольно.
 */
const PROFILE_TIERS = {
  economy: { factor: 0.0, label: 'эконом', examples: 'Exprof Externa, KBE Engine' },
  standard: { factor: 0.45, label: 'стандарт', examples: 'Rehau Thermo, KBE Energy' },
  premium: { factor: 1.0, label: 'премиум', examples: 'Rehau Brilliant, KBE-88' },
};

/**
 * Холодное дешевле тёплого.
 *
 * Выведено тремя независимыми способами из одного прайса (balkon63.ru):
 *   лоджия под ключ   13 890 / 18 990 = 0.731
 *   балкон под ключ   16 999 / 22 999 = 0.739
 *   цена за м²         5 149 /  7 149 = 0.720
 * Разброс 0.72–0.74. Берём 0.73.
 */
const COLD_FACTOR = 0.73;

/**
 * Надбавки. Проценты, а не рубли: в прайсах они отдельной строкой не указаны,
 * а выводятся из разницы между «остеклением» и «под ключ».
 *
 * ВНИМАНИЕ: это единственные оценочные коэффициенты в файле, и они помечены
 * как таковые в выводе. Их следует заменить на реальный прайс клиента при
 * внедрении — именно об этом надо говорить на встрече.
 */
const MODIFIERS = {
  topFloor: { factor: 0.18, label: 'крыша (последний этаж)', estimated: true },
  extension: { factor: 0.22, label: 'вынос до 30 см', estimated: true },
};

/** Минимальные цены по рынку — нижняя граница санитарной проверки. */
const MARKET_FLOOR = {
  cold: 13890, // «Лоджия (холодное остекление)» под ключ, balkon63.ru
  warm: 18050, // Exprof Externa, прямой балкон 3 м, balkon63.ru
};

function clampConfig(v) {
  return Object.prototype.hasOwnProperty.call(WARM_BY_CONFIG, v) ? v : 'straight3';
}

function clampTier(v) {
  return Object.prototype.hasOwnProperty.call(PROFILE_TIERS, v) ? v : null;
}

function roundTo(value, step) {
  return Math.round(value / step) * step;
}

/**
 * Оценить стоимость остекления.
 *
 * @param {object} input
 * @param {string} input.configuration  straight3 | pshaped | loggia6
 * @param {string} input.glazing        cold | warm
 * @param {string} [input.profileTier]  economy | standard | premium; без него
 *                                      возвращается вся вилка по профилям
 * @param {boolean} [input.topFloor]    последний этаж — нужна крыша
 * @param {boolean} [input.extension]   с выносом
 * @returns {object} { low, high, currency, breakdown, assumptions, includes, excludes }
 */
function estimate(input) {
  const inp = input || {};
  const configuration = clampConfig(inp.configuration);
  const glazing = inp.glazing === 'cold' ? 'cold' : 'warm';
  const tier = clampTier(inp.profileTier);

  const base = WARM_BY_CONFIG[configuration];
  const assumptions = [];
  const breakdown = [];

  // Базовая вилка по профилям
  let low = base.low;
  let high = base.high;

  if (tier) {
    // Конкретный класс профиля — сужаем вилку вокруг точки на шкале.
    const f = PROFILE_TIERS[tier].factor;
    const span = base.high - base.low;
    const point = base.low + span * f;
    // ±8 % — разброс между марками внутри одного класса.
    low = point * 0.92;
    high = point * 1.08;
    assumptions.push(
      `класс профиля: ${PROFILE_TIERS[tier].label} (${PROFILE_TIERS[tier].examples})`
    );
  } else {
    assumptions.push('класс профиля не выбран — показана вилка от эконома до премиума');
  }

  breakdown.push({
    item: `Остекление, ${base.label}`,
    low: Math.round(low),
    high: Math.round(high),
  });

  if (glazing === 'cold') {
    low *= COLD_FACTOR;
    high *= COLD_FACTOR;
    breakdown.push({
      item: 'Холодное остекление вместо тёплого',
      low: -Math.round(breakdown[0].low * (1 - COLD_FACTOR)),
      high: -Math.round(breakdown[0].high * (1 - COLD_FACTOR)),
    });
  }

  for (const key of ['topFloor', 'extension']) {
    if (!inp[key]) continue;
    const m = MODIFIERS[key];
    const addLow = low * m.factor;
    const addHigh = high * m.factor;
    low += addLow;
    high += addHigh;
    breakdown.push({ item: m.label, low: Math.round(addLow), high: Math.round(addHigh) });
    if (m.estimated) assumptions.push(`${m.label} — коэффициент оценочный, уточняется на замере`);
  }

  // Округляем ПЕРЕД проверкой на минимум. Иначе округление вниз до 500 может
  // само увести цифру ниже рынка — так и случилось при первом прогоне тестов:
  // 13 600 превращалось в 13 500, то есть в обещание, которого никто на рынке
  // не даёт.
  let roundedLow = roundTo(low, 500);
  let roundedHigh = roundTo(high, 500);

  const floor = MARKET_FLOOR[glazing];
  let flooredTo = null;
  if (roundedLow < floor) {
    flooredTo = floor;
    roundedLow = floor;
    if (roundedHigh < roundedLow) roundedHigh = roundTo(roundedLow * 1.15, 500);
  }

  return {
    low: roundedLow,
    high: roundedHigh,
    currency: 'RUB',
    configuration,
    configurationLabel: base.label,
    glazing,
    breakdown,
    assumptions,
    flooredTo,
    // Перечень «что входит» — дословно из balkon63.ru: «монтаж подоконников,
    // козырьков от верхнего этажа, водоотливов, нащельников и герметизация
    // конструкции остекления». Не наша выдумка.
    includes: [
      'монтаж конструкции',
      'подоконники',
      'козырьки',
      'водоотливы и нащельники',
      'герметизация',
    ],
    excludes: [
      'внутренняя отделка',
      'утепление',
      'электрика и тёплый пол',
      'шкафы и мебель',
    ],
  };
}

/** Человекочитаемая вилка: «от 18 000 до 37 000 ₽». */
function formatRange(result) {
  const fmt = (n) => n.toLocaleString('ru-RU');
  if (!result || result.low == null) return 'не удалось рассчитать';
  if (result.low === result.high) return `${fmt(result.low)} ₽`;
  return `от ${fmt(result.low)} до ${fmt(result.high)} ₽`;
}

